export class FeatureFlags {
    constructor({ schema, environment, defaults: defaultsInput, overrides, subscription, }) {
        Object.defineProperty(this, "subscriptions", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: []
        });
        Object.defineProperty(this, "schema", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "initialStore", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "_store", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        if (defaultsInput && !environment) {
            throw new Error("Got defaults but no environment");
        }
        const defaults = defaultsInput && environment && environment in defaultsInput
            ? defaultsInput[environment]
            : undefined;
        this.schema = schema;
        this._store = new Proxy(FeatureFlags.computeStore({ schema, defaults, overrides }), {
            set: (store, flag, value) => {
                if (typeof flag !== "string")
                    return false;
                const valid = value === FeatureFlags.computeValue({
                    schema: this.schema,
                    flag,
                    current: flag in store
                        ? store[flag]
                        : undefined,
                    manual: value,
                });
                if (!valid)
                    return false;
                const success = Reflect.set(store, flag, value);
                if (success)
                    this.subscriptions.map((f) => f(flag, value));
                return success;
            },
        });
        this.initialStore = { ...this._store };
        if (subscription)
            this.subscriptions.push(subscription);
    }
    subscribe(subscription) {
        this.subscriptions.push(subscription);
        return true;
    }
    unsubscribe(subscription) {
        const index = this.subscriptions.indexOf(subscription);
        if (index)
            this.subscriptions.splice(index, 1);
        return !!index;
    }
    get store() {
        return this._store;
    }
    get(flag) {
        return this._store[flag];
    }
    set(flag, value) {
        this._store[flag] = value;
        return true;
    }
    static computeStore({ schema, defaults, overrides, }) {
        const options = FeatureFlags.listOptionsFromSchema(schema);
        return options.reduce((prev, flag) => ({
            ...prev,
            [flag]: FeatureFlags.computeValue({
                schema,
                defaults,
                overrides,
                flag,
            }),
        }), {});
    }
    static computeValue({ schema, flag, overrides, defaults, current: vCurrent, manual, }) {
        const v = (v) => schema[flag].options.includes(v)
            ? v
            : undefined;
        const vSchema = schema[flag].options[0];
        const vDefault = v(defaults?.[flag]);
        const vOverride = v(FeatureFlags.computeOverride({ schema, flag, overrides }));
        const vManual = v(!schema[flag].readonly ? manual : undefined);
        return vManual ?? vOverride ?? vDefault ?? vCurrent ?? vSchema;
    }
    static computeOverride({ schema, flag, overrides, }) {
        if (schema[flag].readonly)
            return undefined;
        const value = overrides?.(flag);
        if (!FeatureFlags.isValidValue(value))
            return undefined;
        return value;
    }
    static listOptionsFromSchema(schema) {
        return Object.keys(schema);
    }
    static isValidValue(v) {
        return ["string", "number", "boolean"].includes(typeof v);
    }
    static createOptions({ schema, defaults, }) {
        return { schema, defaults };
    }
}
